#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int highestBit = 0;
    while ((1LL << (highestBit + 1)) <= n)
        ++highestBit;

    int previous[30][2] = {};
    int current[30][2] = {};

    previous[highestBit][0] = 1;
    if (highestBit > 0 && n >= 3LL * (1LL << (highestBit - 1)))
        previous[highestBit - 1][1] = 1;

    for (int i = 2; i <= n; ++i) {
        memset(current, 0, sizeof(current));

        for (int j = 0; j <= highestBit; ++j) {
            long long power = 1LL << j;
            long long count0 = n / power - (i - 1LL);
            long long count1 = n / (3LL * power) - (i - 1LL);

            if (count0 >= 0) {
                current[j][0] = (current[j][0] +
                    previous[j][0] * count0) % MOD;
            }

            if (count1 >= 0) {
                current[j][1] = (current[j][1] +
                    previous[j][1] * count1) % MOD;
            }

            if (j < highestBit) {
                long long delta0 = n / power - n / (power * 2);
                long long delta1 = n / (power * 3) - n / (power * 6);

                current[j][0] = (current[j][0] +
                    previous[j + 1][0] * delta0) % MOD;
                current[j][1] = (current[j][1] +
                    previous[j + 1][1] * delta1) % MOD;
            }

            long long delta = n / power - n / (power * 3);
            current[j][0] = (current[j][0] +
                previous[j][1] * delta) % MOD;
        }

        memcpy(previous, current, sizeof(previous));
    }

    cout << previous[0][0] << '\n';
    return 0;
}

