            long long power = 1LL << j;
            long long count0 = n / power - (i - 1LL);
            long long count1 = n / (3LL * power) - (i - 1LL);

            if (count0 >= 0)
                cur[j][0] = (cur[j][0] + prev[j][0] * count0) % P;

            if (count1 >= 0)
                cur[j][1] = (cur[j][1] + prev[j][1] * count1) % P;

            if (j < cnt_bit) {
                long long diff0 = n / power - n / (power * 2);
                long long diff1 = n / (3LL * power) - n / (6LL * power);

                cur[j][0] = (cur[j][0] + prev[j + 1][0] * diff0) % P;
                cur[j][1] = (cur[j][1] + prev[j + 1][1] * diff1) % P;
            }

            long long diff = n / power - n / (3LL * power);
            cur[j][0] = (cur[j][0] + prev[j][1] * diff) % P;
        }

        prev.swap(cur);
