    read(n);

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int now = 1;
    int cnt_bit = 0;
    while (now <= n) {
        now *= 2;
        ++cnt_bit;
    }
    --cnt_bit;

    f[1][cnt_bit][0] = 1;
    if (cnt_bit > 0 && n >= 3 * (1 << (cnt_bit - 1)))
        f[1][cnt_bit - 1][1] = 1;

    for (int i = 2; i <= n; ++i) {
        for (int j = 0; j <= cnt_bit; ++j) {
            int power = 1 << j;
            int count0 = n / power;
            int count1 = n / (3 * power);

            if (count0 >= i - 1) {
                f[i][j][0] = (f[i][j][0] +
                    1LL * f[i - 1][j][0] * (count0 - (i - 1))) % P;
            }

            if (count1 >= i - 1) {
                f[i][j][1] = (f[i][j][1] +
                    1LL * f[i - 1][j][1] * (count1 - (i - 1))) % P;
            }

            if (j < cnt_bit) {
                int nextPower = 1 << (j + 1);
                f[i][j][0] = (f[i][j][0] +
                    1LL * f[i - 1][j + 1][0] *
                    (n / power - n / nextPower)) % P;

                f[i][j][1] = (f[i][j][1] +
                    1LL * f[i - 1][j + 1][1] *
                    (n / (3 * power) - n / (3 * nextPower))) % P;
            }

            f[i][j][0] = (f[i][j][0] +
                1LL * f[i - 1][j][1] * (count0 - count1)) % P;
        }
    }

    cout << f[n][0][0] << '\n';
    return 0;
}

