constexpr int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int maxBit = 31 - __builtin_clz(n);
    int previous[31][2] = {};
    int current[31][2] = {};

    previous[maxBit][0] = 1;
    if (maxBit > 0 && n >= 3LL * (1LL << (maxBit - 1)))
        previous[maxBit - 1][1] = 1;

    auto addProduct = [](int& value, int state, long long multiplier) {
        value = (value + 1LL * state * multiplier % MOD) % MOD;
    };

    for (int i = 2; i <= n; ++i) {
        memset(current, 0, sizeof(current));

        for (int j = 0; j <= maxBit; ++j) {
            long long power = 1LL << j;
            long long count0 = n / power;
            long long count1 = n / (3LL * power);

            if (count0 >= i - 1)
                addProduct(current[j][0], previous[j][0],
                           count0 - (i - 1));

            if (count1 >= i - 1)
                addProduct(current[j][1], previous[j][1],
                           count1 - (i - 1));

            if (j < maxBit) {
                addProduct(current[j][0], previous[j + 1][0],
                           count0 - n / (power * 2));

                addProduct(current[j][1], previous[j + 1][1],
                           count1 - n / (power * 6));
            }

            addProduct(current[j][0], previous[j][1], count0 - count1);
        }

        memcpy(previous, current, sizeof(previous));
    }

    cout << previous[0][0] << '\n';
    return 0;
}

